INSERT OR IGNORE INTO settings(key,value) VALUES('kpi_change_threshold','20');
ALTER TABLE kpi_templates ADD COLUMN seniority_id INTEGER REFERENCES seniorities(id);
ALTER TABLE reports ADD COLUMN role_data TEXT NOT NULL DEFAULT '{}';
ALTER TABLE reports ADD COLUMN role_title TEXT NOT NULL DEFAULT '';
CREATE TABLE report_templates(id INTEGER PRIMARY KEY, position_id INTEGER NOT NULL UNIQUE REFERENCES positions(id), questions TEXT NOT NULL);
CREATE TABLE review_discussions(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), report_id INTEGER REFERENCES reports(id), kpi_id INTEGER REFERENCES kpis(id), parent_id INTEGER REFERENCES review_discussions(id), author_id INTEGER NOT NULL REFERENCES employees(id), comment TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE monthly_survey_receipts(user_id INTEGER NOT NULL REFERENCES users(id), month TEXT NOT NULL, survey_id INTEGER NOT NULL REFERENCES surveys(id), PRIMARY KEY(user_id,month));
INSERT OR IGNORE INTO monthly_survey_receipts(user_id,month,survey_id) SELECT r.user_id,substr(s.start,1,7),r.survey_id FROM survey_receipts r JOIN surveys s ON s.id=r.survey_id ORDER BY s.id;
CREATE TABLE complaint_bookmarks(token_hash TEXT PRIMARY KEY, complaint_id INTEGER NOT NULL REFERENCES complaints(id));
CREATE TABLE termination_requests(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), initiated_by INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, supporting_document TEXT NOT NULL, notice_date TEXT NOT NULL, proposed_end TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending HR review', hr_review TEXT DEFAULT '', legal_review TEXT DEFAULT '', approved_by INTEGER REFERENCES users(id), settlement TEXT DEFAULT '', access_closed INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE courses ADD COLUMN provider TEXT DEFAULT '';
ALTER TABLE courses ADD COLUMN category TEXT DEFAULT '';
ALTER TABLE courses ADD COLUMN description TEXT DEFAULT '';
ALTER TABLE courses ADD COLUMN difficulty INTEGER NOT NULL DEFAULT 1 CHECK(difficulty BETWEEN 1 AND 5);
ALTER TABLE courses ADD COLUMN target_roles TEXT DEFAULT '';
ALTER TABLE courses ADD COLUMN completion_requirements TEXT DEFAULT '';
ALTER TABLE courses ADD COLUMN status TEXT NOT NULL DEFAULT 'Active';
CREATE TABLE ai_messages(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), conversation_id TEXT NOT NULL, role TEXT NOT NULL, message TEXT NOT NULL, scope_hash TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
